create table if not exists categories(id uuid primary key default gen_random_uuid(), name text, slug text unique, type text, created_at timestamptz default now());
create table if not exists admins(user_id uuid primary key);
create table if not exists apps(id uuid primary key default gen_random_uuid(), name text, slug text unique, description text, logo_url text, screenshots text[] default '{}', category_id uuid references categories(id), size text, version text, os text[] default '{}', download_links jsonb default '[]', price numeric default 0, is_featured boolean default false, downloads int default 0, created_at timestamptz default now());
create table if not exists videos(id uuid primary key default gen_random_uuid(), title text, slug text unique, description text, thumbnail_url text, video_url text, youtube_id text, category_id uuid references categories(id), is_featured boolean default false, views int default 0, created_at timestamptz default now());
create table if not exists articles(id uuid primary key default gen_random_uuid(), title text, slug text unique, content text, cover_url text, category_id uuid references categories(id), tags text[] default '{}', seo_title text, seo_description text, status text default 'draft', published_at timestamptz, created_at timestamptz default now());
create table if not exists links(id uuid primary key default gen_random_uuid(), title text, description text, image_url text, url text, category text, created_at timestamptz default now());
create table if not exists newsletter_subscribers(id uuid primary key default gen_random_uuid(), email text unique, confirmed boolean default false, created_at timestamptz default now());
create table if not exists comments(id uuid primary key default gen_random_uuid(), user_id uuid, target_type text, target_id uuid, content text, approved boolean default true, created_at timestamptz default now());
create table if not exists downloads(id uuid primary key default gen_random_uuid(), app_id uuid references apps(id), user_id uuid, created_at timestamptz default now());
